import os
import re
from typing import Any, Dict, List, Optional

import requests


class TextSafety:
    def __init__(
        self,
        api_key: Optional[str] = None,
        threshold: float = 0.7,
        timeout: int = 20,
        language: str = "en",
    ) -> None:
        self.api_key = api_key or os.environ["TISANE_API_KEY"]
        self.threshold = threshold
        self.timeout = timeout
        self.language = language
        self.base_url = "https://api.tisane.ai"

    def analyze_text(self, text: str) -> Dict[str, Any]:
        url = f"{self.base_url}/parse"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/json",
        }
        payload = {
            "language": self.language,
            "content": text,
            "settings": {
                "snippets": True,
            },
        }

        response = requests.post(url, headers=headers, json=payload, timeout=self.timeout)
        response.raise_for_status()
        return response.json()

    def flag_unsafe_spans(self, text: str) -> Dict[str, Any]:
        result = self.analyze_text(text)
        spans = self._extract_unsafe_spans(result, text)
        flagged = len(spans) > 0
        return {
            "provider": "Tisane",
            "flagged": flagged,
            "spans": spans,
            "raw_response": result,
        }

    def redact_unsafe_spans(self, text: str, replacement: str = "[REDACTED]") -> Dict[str, Any]:
        result = self.flag_unsafe_spans(text)
        spans = result["spans"]
        redacted_text = self._apply_redactions(text, spans, replacement)
        return {
            "provider": "Tisane",
            "flagged": result["flagged"],
            "spans": spans,
            "redacted_text": redacted_text,
            "raw_response": result["raw_response"],
        }

    def _extract_unsafe_spans(self, data: Dict[str, Any], text: str) -> List[Dict[str, Any]]:
        spans: List[Dict[str, Any]] = []

        abuse = data.get("abuse", [])
        for item in abuse:
            severity = self._to_float(item.get("severity"), default=0.0)
            if severity < self.threshold:
                continue

            tags = item.get("tags") or []
            text_fragments = item.get("text") or []
            if isinstance(text_fragments, str):
                text_fragments = [text_fragments]

            for fragment in text_fragments:
                if not fragment:
                    continue
                for start, end in self._find_all_occurrences(text, fragment):
                    spans.append(
                        {
                            "start": start,
                            "end": end,
                            "text": text[start:end],
                            "labels": tags,
                            "score": severity,
                        }
                    )

        for entity in data.get("entities_summary", []) or []:
            sentiment = (entity.get("sentiment") or {}).get("polarity")
            if sentiment == "negative":
                phrase = entity.get("name")
                confidence = self._to_float(
                    (entity.get("sentiment") or {}).get("score"), default=0.0
                )
                if phrase and confidence >= self.threshold:
                    for start, end in self._find_all_occurrences(text, phrase):
                        spans.append(
                            {
                                "start": start,
                                "end": end,
                                "text": text[start:end],
                                "labels": ["negative_entity"],
                                "score": confidence,
                            }
                        )

        spans = self._merge_spans(spans)
        return spans

    def _find_all_occurrences(self, text: str, fragment: str) -> List[tuple]:
        if not fragment:
            return []
        matches = []
        for m in re.finditer(re.escape(fragment), text, flags=re.IGNORECASE):
            matches.append((m.start(), m.end()))
        return matches

    def _merge_spans(self, spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []

        spans = sorted(spans, key=lambda x: (x["start"], x["end"]))
        merged: List[Dict[str, Any]] = [spans[0].copy()]

        for span in spans[1:]:
            current = merged[-1]
            if span["start"] <= current["end"]:
                current["end"] = max(current["end"], span["end"])
                current["text"] = current["text"] + ""
                current["labels"] = sorted(set(current.get("labels", []) + span.get("labels", [])))
                current["score"] = max(
                    self._to_float(current.get("score"), 0.0),
                    self._to_float(span.get("score"), 0.0),
                )
            else:
                merged.append(span.copy())

        for item in merged:
            item["text"] = item.get("text") or ""
        return merged

    def _apply_redactions(
        self,
        text: str,
        spans: List[Dict[str, Any]],
        replacement: str,
    ) -> str:
        if not spans:
            return text

        parts = []
        cursor = 0
        for span in sorted(spans, key=lambda x: x["start"]):
            start = max(0, min(len(text), span["start"]))
            end = max(start, min(len(text), span["end"]))
            if start > cursor:
                parts.append(text[cursor:start])
            parts.append(replacement)
            cursor = end
        if cursor < len(text):
            parts.append(text[cursor:])
        return "".join(parts)

    def _to_float(self, value: Any, default: float = 0.0) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return default


def flag_unsafe_spans(text: str, threshold: float = 0.7) -> Dict[str, Any]:
    return TextSafety(threshold=threshold).flag_unsafe_spans(text)


def redact_unsafe_spans(
    text: str,
    threshold: float = 0.7,
    replacement: str = "[REDACTED]",
) -> Dict[str, Any]:
    return TextSafety(threshold=threshold).redact_unsafe_spans(text, replacement=replacement)
